<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Panel | Jenlu Sv</title><style>:root{--ink:#342d3b;--muted:#756e7b;--cream:#fffaf4;--lilac:#e9ddfb;--line:#ded5df}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:Arial,Helvetica,sans-serif}.wrap{width:min(1120px,calc(100% - 36px));margin:auto}header{padding:22px 0;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);gap:15px}.brand{font:28px Georgia,serif;font-weight:bold}.brand span{color:#c581a2}.links{display:flex;gap:17px}.links a{color:var(--muted);font-size:14px;text-decoration:none}.intro{padding:36px 0 22px}h1,h2,h3{font-family:Georgia,serif}h1{font-size:38px;margin:0 0 7px}p{color:var(--muted)}.message{padding:12px 14px;border-radius:10px;background:var(--lilac);margin:14px 0}.columns{display:grid;grid-template-columns:380px 1fr;gap:28px;align-items:start;margin-bottom:50px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px}h2{margin-top:0;font-size:25px}label{display:block;font-size:14px;font-weight:bold;margin:14px 0 6px}input,textarea,select{width:100%;font:inherit;padding:10px;border:1px solid #d9d0dc;border-radius:9px;background:#fff}textarea{min-height:95px;resize:vertical}button{font:inherit;cursor:pointer}.primary{width:100%;margin-top:18px;padding:12px;border:0;border-radius:999px;background:var(--ink);color:#fff}.products{display:grid;gap:11px}.product{display:grid;grid-template-columns:76px 1fr auto;gap:13px;align-items:center;padding:10px;border:1px solid var(--line);border-radius:12px}.product img{width:76px;height:65px;object-fit:cover;border-radius:8px;background:var(--lilac)}.product strong{display:block}.product small{color:var(--muted)}.actions{display:flex;gap:7px;flex-wrap:wrap}.link-button,.delete{border:1px solid var(--ink);color:var(--ink);border-radius:999px;background:#fff;padding:8px 11px;font-size:13px;text-decoration:none}.delete{border-color:#bd6a77;color:#9c3d4d}.edit{margin-bottom:25px}.thumbs{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.thumb{position:relative}.thumb img{width:76px;height:70px;object-fit:cover;border-radius:8px}.remove-image{position:absolute;right:-5px;top:-6px;border:0;background:#9c3d4d;color:#fff;border-radius:50%;width:21px;height:21px;padding:0;line-height:1}.hint{font-size:12px;color:var(--muted);line-height:1.4}@media(max-width:760px){.columns{grid-template-columns:1fr}.product{grid-template-columns:60px 1fr}.product img{width:60px;height:55px}.actions{grid-column:2}header{align-items:flex-start}}</style></head><body><main class="wrap"><header><div class="brand">Jenlu <span>Sv</span></div><nav class="links"><a href="index.php" target="_blank">Ver tienda</a><a href="admin.php?logout=1">Cerrar sesión</a></nav></header><section class="intro"><h1>Hola, <?= htmlspecialchars($_SESSION['admin']['username'], ENT_QUOTES, 'UTF-8') ?></h1><p>Administra la información y las fotos de cada arreglo.</p></section><?php if ($message): ?><div class="message"><?= htmlspecialchars($message, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><?php if ($editing): ?><section class="card edit"><h2>Editar: <?= htmlspecialchars($editing['name'], ENT_QUOTES, 'UTF-8') ?></h2><form method="post"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?= (int)$editing['id'] ?>"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><label>Categoría</label><select name="category_id" required><?php foreach($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= (int)$category['id']===(int)$editing['category_id']?'selected':'' ?>><?= htmlspecialchars($category['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><label>Nombre</label><input name="name" value="<?= htmlspecialchars($editing['name'], ENT_QUOTES, 'UTF-8') ?>" required><label>Descripción</label><textarea name="description" required><?= htmlspecialchars($editing['description'], ENT_QUOTES, 'UTF-8') ?></textarea><label>Precio (USD)</label><input name="price" type="number" min="0.01" step="0.01" value="<?= htmlspecialchars((string)$editing['price'], ENT_QUOTES, 'UTF-8') ?>" required><button class="primary">Guardar cambios</button></form><h3>Perspectivas del producto</h3><div class="thumbs"><?php foreach($editing['images'] as $image): ?><div class="thumb"><img src="<?= htmlspecialchars($image['url'], ENT_QUOTES, 'UTF-8') ?>" alt="<?= htmlspecialchars($image['label'], ENT_QUOTES, 'UTF-8') ?>"><form method="post"><input type="hidden" name="action" value="delete_image"><input type="hidden" name="product_id" value="<?= (int)$editing['id'] ?>"><input type="hidden" name="image_id" value="<?= (int)$image['id'] ?>"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><button class="remove-image" title="Eliminar imagen">×</button></form></div><?php endforeach; ?></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="add_images"><input type="hidden" name="product_id" value="<?= (int)$editing['id'] ?>"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><label>Agregar más fotos</label><input name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple required><p class="hint">Puedes seleccionar varias fotos de distintos ángulos. Máximo 5 MB cada una.</p><button class="primary">Agregar perspectivas</button></form><p><a href="admin.php">← Terminar edición</a></p></section><?php endif; ?><section class="columns"><form class="card" method="post" enctype="multipart/form-data"><h2>Nuevo producto</h2><input type="hidden" name="action" value="create"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><label>Categoría</label><select name="category_id" required><option value="">Selecciona una categoría</option><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>"><?= htmlspecialchars($category['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><label>Nombre del arreglo</label><input name="name" maxlength="120" required><label>Descripción</label><textarea name="description" required></textarea><label>Precio (USD)</label><input name="price" type="number" min="0.01" step="0.01" required><label>Fotos del producto</label><input name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple required><p class="hint">Selecciona una o varias fotos: frontal, lateral, detalle, etc.</p><button class="primary">Publicar producto</button></form><section class="card"><h2>Productos publicados</h2><div class="products"><?php foreach ($products as $product): ?><article class="product"><img src="<?= htmlspecialchars($product['image_url'] ?: 'https://placehold.co/200x200', ENT_QUOTES, 'UTF-8') ?>" alt=""><div><strong><?= htmlspecialchars($product['name'], ENT_QUOTES, 'UTF-8') ?></strong><small><?= htmlspecialchars($product['category_name'], ENT_QUOTES, 'UTF-8') ?> · $<?= number_format((float)$product['price'],2) ?></small></div><div class="actions"><a class="link-button" href="admin.php?edit=<?= (int)$product['id'] ?>">Editar</a><form method="post" onsubmit="return confirm('¿Eliminar este producto?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><button class="delete">Eliminar</button></form></div></article><?php endforeach; ?></div></section></section></main></body></html>
